const tabId = 1854033387;

// Fetch all 437 products from women-one-piece
const allData = await browserjs(tabId, async () => {
  let products = [];
  let page = 1;
  while (true) {
    const resp = await fetch(`/collections/women-one-piece/products.json?limit=250&page=${page}`);
    if (!resp.ok) break;
    const data = await resp.json();
    if (!data.products || data.products.length === 0) break;
    products.push(...data.products);
    if (data.products.length < 250) break;
    page++;
  }

  // Find all products that are Black and have any discount
  const discountedBlack = [];
  for (const p of products) {
    const isBlack = (p.tags && p.tags.some(t => t.toLowerCase() === 'black')) ||
                    p.title.toLowerCase().includes('black') ||
                    p.handle.toLowerCase().includes('black');
    if (!isBlack) continue;

    for (const v of p.variants) {
      const price = parseFloat(v.price);
      const comparePrice = v.compare_at_price ? parseFloat(v.compare_at_price) : null;
      if (comparePrice && comparePrice > price) {
        const discountPercent = ((comparePrice - price) / comparePrice) * 100;
        discountedBlack.push({
          productId: p.id,
          title: p.title,
          handle: p.handle,
          variantId: v.id,
          variantTitle: v.title,
          price,
          comparePrice,
          discountPercent: Math.round(discountPercent * 100) / 100,
          available: v.available
        });
      }
    }
  }

  return discountedBlack;
});

