const plpInStockSales = await browserjs(tabId, async () => {
  // We already fetched the 96 cards from the 4 pages of the filtered PLP:
  // Let's inspect each card that is On Sale or has a discount, and check its availability and variants!
  const pages = [1, 2, 3, 4];
  const allCards = [];

  for (const p of pages) {
    const url = `/collections/women-one-piece?filter.p.m.product.color_filter=gid%3A%2F%2Fshopify%2FMetaobject%2F276878098799&filter.v.option.size=gid%3A%2F%2Fshopify%2FFilterSettingGroup%2F150208879&page=${p}`;
    const resp = await fetch(url);
    const html = await resp.text();
    const doc = new DOMParser().parseFromString(html, 'text/html');

    const items = Array.from(doc.querySelectorAll('.card-product, .product-card, .grid__item, [data-product-id], .card-wrapper'));
    for (const item of items) {
      const titleEl = item.querySelector('.card__heading, .card-information__text, h3, a.full-unstyled-link');
      const linkEl = item.querySelector('a.full-unstyled-link, a[href*="/products/"]');
      const badgeEl = item.querySelector('.badge, .card__badge');
      const regularPriceEl = item.querySelector('.price__regular .price-item--regular, .price-item--regular');
      const salePriceEl = item.querySelector('.price__sale .price-item--sale, .price-item--sale');

      if (!titleEl || !linkEl) continue;
      const title = titleEl.textContent.trim();
      const href = linkEl.getAttribute('href');
      const badge = badgeEl ? badgeEl.textContent.trim() : '';
      const regText = regularPriceEl ? regularPriceEl.textContent.trim() : '';
      const saleText = salePriceEl ? salePriceEl.textContent.trim() : '';

      allCards.push({ page: p, title, href, badge, regText, saleText });
    }
  }

  // Deduplicate
  const unique = [];
  const seen = new Set();
  for (const c of allCards) {
    if (!seen.has(c.href)) {
      seen.add(c.href);
      unique.push(c);
    }
  }

  const results = [];
  for (const c of unique) {
    try {
      const u = new URL(c.href, window.location.origin);
      const handle = u.pathname.split('/').pop();
      const linkedVariantId = u.searchParams.get('variant');

      const pResp = await fetch(`/products/${handle}.js`);
      if (!pResp.ok) continue;
      const pData = await pResp.json();

      const linkedVariant = pData.variants.find(v => String(v.id) === String(linkedVariantId)) || pData.variants[0];

      // Check if linkedVariant has discount
      const hasDiscount = linkedVariant.compare_at_price && linkedVariant.compare_at_price > linkedVariant.price;
      const discountPct = hasDiscount ? ((linkedVariant.compare_at_price - linkedVariant.price) / linkedVariant.compare_at_price) * 100 : 0;

      // Also check all variants that have discount and are available
      const availableDiscountedVariants = pData.variants.filter(v => v.available && v.compare_at_price && v.compare_at_price > v.price);

      results.push({
        title: pData.title,
        handle,
        badge: c.badge,
        linkedVariant: {
          id: linkedVariant.id,
          title: linkedVariant.title,
          price: linkedVariant.price / 100,
          compare_at_price: linkedVariant.compare_at_price ? linkedVariant.compare_at_price / 100 : null,
          available: linkedVariant.available,
          discountPct: Math.round(discountPct * 100) / 100
        },
        availableDiscountedVariants: availableDiscountedVariants.map(v => ({
          id: v.id,
          title: v.title,
          price: v.price / 100,
          compare_at_price: v.compare_at_price / 100,
          discountPct: Math.round(((v.compare_at_price - v.price) / v.compare_at_price) * 10000) / 100
        }))
      });
    } catch (e) {
      console.error(e);
    }
  }

  return results;
});

