const tabId = 1854033387;
const analysis = await browserjs(tabId, async () => {
  let products = [];
  let page = 1;
  while (true) {
    const resp = await fetch(`/collections/women-one-piece/products.json?limit=250&page=${page}`);
    if (!resp.ok) break;
    const data = await resp.json();
    if (!data.products || data.products.length === 0) break;
    products.push(...data.products);
    if (data.products.length < 250) break;
    page++;
  }

  // Check unique option values for "Size"
  const sizeValues = new Set();
  const optionNames = new Set();
  for (const p of products) {
    for (const opt of p.options) {
      optionNames.add(opt.name);
      if (opt.name.toLowerCase().includes('size')) {
        opt.values.forEach(v => sizeValues.add(v));
      }
    }
  }

  // Check products that have "L" or "Large" in their size options
  const lProducts = [];
  for (const p of products) {
    for (const v of p.variants) {
      const optStr = [v.option1, v.option2, v.option3].filter(Boolean).join(' ');
      if (/\b(l|large)\b/i.test(optStr)) {
        lProducts.push({
          title: p.title,
          handle: p.handle,
          variant: v
        });
      }
    }
  }

  return {
    totalProducts: products.length,
    optionNames: Array.from(optionNames),
    sizeValues: Array.from(sizeValues).sort(),
    lProductsCount: lProducts.length,
    sampleLProducts: lProducts.slice(0, 10)
  };
});

console.log("Analysis:", JSON.stringify(analysis, null, 2));

