                       p.title.toLowerCase().includes('hydrasuit') ||
                       p.title.toLowerCase().includes('legsuit');
    const isNotBikini = !p.title.toLowerCase().includes('bikini') && !p.title.toLowerCase().includes('two piece') && !p.tags.includes('Bikinis & Tankinis');

