    const isBlack = tagsLower.includes('black') || titleLower.includes('black') || handleLower.includes('black');

    if (isWomen && isOnePiece && isNotTwoPiece && isBlack) {
      for (const v of p.variants) {
        if (v.title.trim().toUpperCase() === 'L' || v.title.trim().toLowerCase() === 'large') {
          const regular = v.compare_at_price ? parseFloat(v.compare_at_price) : parseFloat(v.price);
