      const pResp = await fetch(`/products/${handle}.js`);
      if (!pResp.ok) continue;
      const pData = await pResp.json();

      const linkedVariant = pData.variants.find(v => String(v.id) === String(linkedVariantId)) || pData.variants[0];

      // Check if linkedVariant has discount
      const hasDiscount = linkedVariant.compare_at_price && linkedVariant.compare_at_price > linkedVariant.price;
      const discountPct = hasDiscount ? ((linkedVariant.compare_at_price - linkedVariant.price) / linkedVariant.compare_at_price) * 100 : 0;

      // Also check all variants that have discount and are available
      const availableDiscountedVariants = pData.variants.filter(v => v.available && v.compare_at_price && v.compare_at_price > v.price);

      results.push({
        title: pData.title,
        handle,
        badge: c.badge,
        linkedVariant: {
          id: linkedVariant.id,
          title: linkedVariant.title,
          price: linkedVariant.price / 100,
          compare_at_price: linkedVariant.compare_at_price ? linkedVariant.compare_at_price / 100 : null,
          available: linkedVariant.available,
          discountPct: Math.round(discountPct * 100) / 100
        },
        availableDiscountedVariants: availableDiscountedVariants.map(v => ({
          id: v.id,
          title: v.title,
          price: v.price / 100,
          compare_at_price: v.compare_at_price / 100,
          discountPct: Math.round(((v.compare_at_price - v.price) / v.compare_at_price) * 10000) / 100
        }))
      });
    } catch (e) {
      console.error(e);
    }
  }

  return results;
});

// Filter for products where linkedVariant is available and has discount > 0
const availableLinked = plpInStockSales.filter(p => p.linkedVariant.available && p.linkedVariant.discountPct > 0);
availableLinked.sort((a, b) => b.linkedVariant.discountPct - a.linkedVariant.discountPct);

console.log("Products where linked variant on filtered PLP is available & discounted:", availableLinked.length);
