const tabId = 1854033387;

const checkLiteralInOtherCollections = await browserjs(tabId, async () => {
  const fetchAll = async (collection) => {
    let products = [];
    let page = 1;
    while (true) {
      const resp = await fetch(`/collections/${collection}/products.json?limit=250&page=${page}`);
      if (!resp.ok) break;
      const data = await resp.json();
      if (!data.products || data.products.length === 0) break;
      products.push(...data.products);
      if (data.products.length < 250) break;
      page++;
    }
    return products;
  };

  const saleProducts = await fetchAll('women-sale');
  const blackProducts = await fetchAll('women-black-swimsuits');

  const all = [...saleProducts, ...blackProducts];
  const seen = new Set();
  const unique = [];
  for (const p of all) {
    if (!seen.has(p.id)) {
      seen.add(p.id);
      unique.push(p);
    }
  }

  const literalLMatches = [];
  for (const p of unique) {
    const isOnePiece = p.tags.some(t => t.toLowerCase() === 'one piece' || t.toLowerCase() === 'swimsuit') ||
                       p.title.toLowerCase().includes('one piece') ||
                       p.title.toLowerCase().includes('swimsuit') ||
                       p.title.toLowerCase().includes('hydrasuit') ||
                       p.title.toLowerCase().includes('legsuit');
    const isNotTwoPiece = !p.title.toLowerCase().includes('bikini') && !p.title.toLowerCase().includes('two piece') && !p.tags.includes('Bikinis & Tankinis');
    const isBlack = p.tags.some(t => t.toLowerCase() === 'black') || p.title.toLowerCase().includes('black') || p.handle.toLowerCase().includes('black');

    if (isOnePiece && isNotTwoPiece && isBlack) {
      for (const v of p.variants) {
        if (v.title.trim().toUpperCase() === 'L' || v.title.trim().toLowerCase() === 'large') {
          literalLMatches.push({
            title: p.title,
            handle: p.handle,
            variantId: v.id,
            variantTitle: v.title,
            available: v.available,
            price: v.price,
            compare_at_price: v.compare_at_price
          });
        }
      }
    }
  }

  return literalLMatches;
});

console.log("Literal L in sale & black collections:", JSON.stringify(checkLiteralInOtherCollections, null, 2));

