const tabId = 1854033387;

const cartDetails = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('.cart-item, [data-cart-item], .cart__items tr, form[action*="/cart"] table tr'))
    .map(tr => tr.innerText.replace(/\s+/g, ' '));
  const subtotal = document.querySelector('.totals__subtotal-value, .cart__subtotal, .cart__total')?.textContent.trim();
  const headings = Array.from(document.querySelectorAll('h1, h2, h3')).map(h => h.textContent.trim());

  return {
    headings,
    subtotal,
    items: items.filter(t => t.length > 0)
  };
});

console.log("Cart details:", JSON.stringify(cartDetails, null, 2));

